"""Turn P2's real proof (zk/out/fixture/fixture.json) into contracts/test/Fixture.sol.

Run from anywhere:  python contracts/gen_fixture.py
Re-run whenever P2 regenerates the fixture. Never edit Fixture.sol by hand.
"""
import json
from pathlib import Path

HERE = Path(__file__).resolve().parent
f = json.loads((HERE.parent / "zk" / "out" / "fixture" / "fixture.json").read_text())


def arr(xs, t="uint256"):
    return "[" + ", ".join(f"{t}({x})" if i == 0 else str(x) for i, x in enumerate(xs)) + "]"


pB = f["pB"]
out = f"""// SPDX-License-Identifier: MIT
// GENERATED by contracts/gen_fixture.py from zk/out/fixture/fixture.json. Do not edit.
pragma solidity ^0.8.24;

library Fixture {{
    address internal constant AGENT = {f['agent_wallet']};
    uint256 internal constant TASK_ID = {f['task_id']};
    bytes32 internal constant TEST_SUITE_HASH = {f['test_suite_hash']};

    function pA() internal pure returns (uint256[2] memory) {{
        return {arr(f['pA'])};
    }}

    function pB() internal pure returns (uint256[2][2] memory) {{
        return [{arr(pB[0])}, {arr(pB[1])}];
    }}

    function pC() internal pure returns (uint256[2] memory) {{
        return {arr(f['pC'])};
    }}

    function pub() internal pure returns (uint256[16] memory) {{
        return {arr(f['pubSignals'])};
    }}
}}
"""
(HERE / "test" / "Fixture.sol").write_text(out, newline="\n")
print("wrote contracts/test/Fixture.sol (", len(f["pubSignals"]), "public signals )")
